// defaultFlagRoute chooses an implicit boundary without binding any flags. A
// sibling selector wins, and a flag's values are never mistaken for selectors.
func (p *Parser) defaultFlagRoute() int {
 d := p.cmd.DefaultSubcommand
 if d == nil { return -1 }
 at := -1
 for i := 0; i < len(p.argv); {
  token := p.argv[i]
  if token == "--" || token == "-" { return at }
  if !isFlagLike(token) {
   if p.findSubcommand(token) != nil || (token == "help" && !p.cmd.DisableHelpSubcommand) { return -1 }
   return at
  }
  var valueFlag *Flag
  var attached string
  hasAttached := false
  if strings.HasPrefix(token, "--") {
   name, value, has := strings.Cut(token[2:], "=")
   parent := p.findLong(name)
   if parent == nil { parent = p.findNegation(name) }
   flag := parent
   if flag == nil {
    for _, f := range d.Flags {
     if slices.Contains(f.Longs, name) || (f.Negate != "" && f.Negate == name) { flag = f; break }
    }
   }
   if flag == nil {
    if (name == "help" && !p.cmd.DisableHelpFlag) || (name == "version" && p.cmd.Version && !p.cmd.DisableVersionFlag) { i++; continue }
    return at
   }
   if parent == nil && at < 0 { at = i }
   if flag.TakesValue && flag.Negate != name { valueFlag, attached, hasAttached = flag, value, has }
  } else {
   for j := 1; j < len(token); j++ {
    parent := p.findShort(token[j])
    flag := parent
    if flag == nil {
     for _, f := range d.Flags { if slices.Contains(f.Shorts, token[j]) { flag = f; break } }
    }
    if flag == nil { return at }
    if parent == nil && at < 0 { at = i }
    if flag.TakesValue {
     valueFlag = flag
     attached = strings.TrimPrefix(token[j+1:], "=")
     hasAttached = j+1 < len(token)
     break
    }
   }
  }
  i++
  if f := valueFlag; f != nil {
   if !hasAttached && !f.RequireEquals && i < len(p.argv) {
    next := p.argv[i]
    if f.AllowHyphenValues || !isFlagLike(next) || (f.AllowNegativeNumbers && isNegativeNumber(next)) { attached, hasAttached = next, true; i++ }
   }
   if !hasAttached && !f.ValueOptional && !f.HasDefaultMissing { return at }
   if f.Variadic {
    var count uint32
    if hasAttached { count = valuesIn(attached, f.Delimiter) }
    for i < len(p.argv) && (f.VarMax == 0 || count < f.VarMax) {
     next := p.argv[i]
     if next == "--" || (f.ValueTerminator != "" && next == f.ValueTerminator) {
      if next != "--" { i++ }; break
     }
     if isFlagLike(next) && !(f.AllowNegativeNumbers && isNegativeNumber(next)) { break }
     if p.cmd.SubcommandPrecedenceOverArg && p.findSubcommand(next) != nil { return -1 }
     count += valuesIn(next, f.Delimiter); i++
    }
   }
  }
 }
 return at
}

